SELECT 
FROM ad_campaign c LEFT JOIN shop s ON s.id=c.shop_id
WHERE c.region=#{region} AND c.is_deleted=FALSE
AND c.audit_status=#{auditStatus}
ORDER BY c.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM ad_campaign c
WHERE c.region=#{region} AND c.is_deleted=FALSE
AND c.audit_status=#{auditStatus}
